charset_normalizer.utils._character_flag:
def _character_flags(character: str) -> int:
    """Compute all name-based classification flags with a single unicodedata.name() call."""
    try:
        desc: str = unicodedata.name(character)
    except ValueError:
        return 0
    flags: int = 0
    if 'LATIN' in desc:
        flags |= _LATIN
    if 'CJK' in desc:
        flags |= _CJK
    if 'HANGUL' in desc:
        flags |= _HANGUL
    if 'KATAKANA' in desc:
        flags |= _KATAKANA
    if 'HIRAGANA' in desc:
        flags |= _HIRAGANA
    if 'THAI' in desc:
        flags |= _THAI
    if 'ARABIC' in desc:
        flags |= _ARABIC
        if 'ISOLATED FORM' in desc:
            flags |= _ARABIC_ISOLATED_FORM
    for kw in _ACCENT_KEYWORDS:
        if kw in desc:
            flags |= _ACCENTUATED
            break
    return flags

requests.utils.select_proxy:
def select_proxy(url, proxies):
    """Select a proxy for the url, if applicable.

    :param url: The url being for the request
    :param proxies: A dictionary of schemes or schemes and hosts to proxy URLs
    """
    proxies = (proxies or {})
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get(urlparts.scheme, proxies.get('all'))
    proxy_keys = [urlparts.scheme + '://' + urlparts.hostname, urlparts.scheme, 'all://' + urlparts.hostname, 'all']
    proxy = None
    for proxy_key in proxy_keys:
        if proxy_key in proxies:
            proxy = proxies[proxy_key]
            break
    return proxy

requests.utils.prepend_scheme_if_needed:
def prepend_scheme_if_needed(url, new_scheme):
    """Given a URL that may or may not have a scheme, prepend the given scheme.
    Does not replace a present scheme with the one provided as an argument.

    :rtype: str
    """
    parsed = parse_url(url)
    (scheme, auth, host, port, path, query, fragment) = parsed
    netloc = parsed.netloc
    if not netloc:
        (netloc, path) = (path, netloc)
    if auth:
        netloc = '@'.join([auth, netloc])
    if scheme is None:
        scheme = new_scheme
    if path is None:
        path = ''
    return urlunparse((scheme, netloc, path, '', query, fragment))

requests.utils.guess_json_utf:
def guess_json_utf(data):
    """
    :rtype: str
    """
    sample = data[:4]
    if sample in (codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE):
        return 'utf-32'
    if sample[:3] == codecs.BOM_UTF8:
        return 'utf-8-sig'
    if sample[:2] in (codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
        return 'utf-16'
    nullcount = sample.count(_null)
    if nullcount == 0:
        return 'utf-8'
    if nullcount == 2:
        if sample[::2] == _null2:
            return 'utf-16-be'
        if sample[1::2] == _null2:
            return 'utf-16-le'
    if nullcount == 3:
        if sample[:3] == _null3:
            return 'utf-32-be'
        if sample[1:] == _null3:
            return 'utf-32-le'
    return None

charset_normalizer.utils.is_separator:
def is_separator(character: str) -> bool:
    if (character.isspace() or character in {'｜', '+', '<', '>'}):
        return True
    character_category: str = unicodedata.category(character)
    return ('Z' in character_category or character_category in {'Po', 'Pd', 'Pc'})

charset_normalizer.utils.remove_accent:
@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def remove_accent(character: str) -> str:
    decomposed: str = unicodedata.decomposition(character)
    if not decomposed:
        return character
    codes: list[str] = decomposed.split(' ')
    return chr(int(codes[0], 16))

requests.utils.urldefragauth:
def urldefragauth(url):
    """
    Given a url remove the fragment and the authentication part.

    :rtype: str
    """
    (scheme, netloc, path, params, query, fragment) = urlparse(url)
    if not netloc:
        (netloc, path) = (path, netloc)
    netloc = netloc.rsplit('@', 1)[-1]
    return urlunparse((scheme, netloc, path, params, query, ''))
